/* xx_iso9660_extractor.c - search raw data for ISO9660.
 *
 * Scans for:
 *   01 43 44 30 30 31 at +32768  (".CD001")
 * (hand-written: the detector establishes this signature outside its
 * 64-byte prefilter window)
 * Offset 0 is always tried as well.
 * Each candidate must be accepted by the iso9660 reader, which also measures it,
 * and named by the detector, both on a view that starts at the candidate.
 * See xx_format_extractor_engine.h.
 *
 * GENERATED by gen_extractors.py from the detector's prefilters.
 */

#include "../xx_format_extractor_engine.h"
#include "xxfclib/formats/iso9660/xx_iso9660.h"

static const uint8_t k_anchor0[] = { 0x01, 0x43, 0x44, 0x30, 0x30, 0x31 };

static const xx_format_search_anchor k_anchors[] = {
    { k_anchor0, sizeof(k_anchor0), 32768U },
};

static const xx_file_type_t k_types[] = { XX_FILE_TYPE_ISO9660 };

static Abstractformat *xx_iso9660_search_open(xx_io_device *window) {
    xx_iso9660 *reader = xx_iso9660_create(window, 0);
    return reader ? &reader->format : NULL;
}

static void xx_iso9660_search_close(Abstractformat *format) {
    /* The format is the first member, so this is the reader itself. */
    xx_iso9660_free((xx_iso9660 *)format);
}

static const xx_format_search_desc k_desc = {
    k_types, sizeof(k_types) / sizeof(k_types[0]),
    k_anchors, sizeof(k_anchors) / sizeof(k_anchors[0]),
    xx_iso9660_search_open, xx_iso9660_search_close
};

static xx_format_search_state *xx_iso9660_create_format_search(
    xx_format_extractor *self, xx_io_device *device, const xx_list_s *options,
    xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_create(&k_desc, device, options, pd);
}

static const xx_format_search_info *xx_iso9660_get_current_format_info(
    xx_format_extractor *self, xx_format_search_state *state) {
    (void)self;
    return xx_format_search_current(state);
}

static bool xx_iso9660_format_search_find_next(xx_format_extractor *self,
                                          xx_format_search_state *state,
                                          xx_pd_struct *pd) {
    (void)self;
    return xx_format_search_find_next(state, pd);
}

static void xx_iso9660_free_format_search(xx_format_extractor *self,
                                     xx_format_search_state *state) {
    (void)self;
    xx_format_search_free(state);
}

xx_format_extractor xx_iso9660_extractor = {
    xx_iso9660_create_format_search,
    xx_iso9660_get_current_format_info,
    xx_iso9660_format_search_find_next,
    xx_iso9660_free_format_search
};
